        if (payments != null) {
            long maxId = 0;
            for (Map<String, Object> payment : payments) {
                long id = ((Number) payment.get("id")).longValue();
                maxId = Math.max(maxId, id);
                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
